public void populate()
{
    NDXD01A lNDXD01A;
    NDXD01AHeaderBOMView lNDXD01AHeaderBOMView;

    delete_from lNDXD01A;

    insert_recordset lNDXD01A
        (CSTR, CART, CVERDB, RVERDB, CSTAB)
    select
        DataAreaId, ItemId, BOMId, Name, SiteId
    from lNDXD01AHeaderBOMView;

    update_recordset lNDXD01A
        setting FAZI = 'U';

}

public static str getVersion()
{
    str version;

    str activeField = SysComputedColumn::returnField(viewstr(NDXD01AHeaderBOMView), tableStr(BOMVersion), fieldStr(BOMVersion, Active));
    str approvedField = SysComputedColumn::returnField(viewstr(NDXD01AHeaderBOMView), tableStr(BOMVersion), fieldStr(BOMVersion, Approved));
    str nameField = SysComputedColumn::returnField(viewstr(NDXD01AHeaderBOMView), tableStr(BOMVersion), fieldStr(BOMVersion, Name));
    str itemIdField = SysComputedColumn::returnField(viewstr(NDXD01AHeaderBOMView), tableStr(BOMVersion), fieldStr(BOMVersion, ItemId));

    str activeExpression = SysComputedColumn::equalExpression(activeField,SysComputedColumn::comparisonLiteral(NoYes::Yes));
    str approvedExpression = SysComputedColumn::equalExpression(approvedField,SysComputedColumn::comparisonLiteral(NoYes::Yes));

    str isActiveAndApproved = SysComputedColumn::and2(activeExpression, approvedExpression);
    str isNotActiveAndApproved = SysComputedColumn::and2(SysComputedColumn::notEqualExpression(activeField,SysComputedColumn::comparisonLiteral(NoYes::Yes)), approvedExpression);

    //        
    version = strFmt("(SELECT cast(count(RecId) + 1  as nvarchar(1))"
       + " FROM BOMVersion"
       + " WHERE BOMVersion.ItemId = %1"
       + " AND BOMVersion.Active = %2"
       + " AND BOMVersion.Approved = %3"
       + " AND BOMVersion.Name >= %4)", itemIdField, activeField, approvedField, nameField);

    return SysComputedColumn::if(isActiveAndApproved,
        SysComputedColumn::returnLiteral('1'),
        SysComputedColumn::if(isNotActiveAndApproved,
            version,
            SysComputedColumn::returnLiteral('0')));

    //Or as Case
    /*return strFmt(@'
        CASE
            WHEN %1 = 1 AND %2 = 1 THEN ''1''
            WHEN %1 = 0 AND %2 = 1 THEN
            CAST((
                SELECT COUNT(V2.RECID) + 1
                FROM %5 V2
                WHERE V2.ITEMID   = %3
                  AND V2.ACTIVE   = %1
                  AND V2.APPROVED = %2
                  AND V2.NAME    >= %4
            ) AS NVARCHAR(10))
        ELSE ''0''
        END',
        activeField,        // %1
        approvedField,      // %2
        itemIdField,        // %3
        nameField,     // %4
        'BOMVersion'       // %5 (Name der View in FROM-Klausel)
    );*/


}
